"""Patches the Android project generated by `flutter create`."""

from pathlib import Path
import shutil
import xml.etree.ElementTree as ET

MANIFEST = Path("android/app/src/main/AndroidManifest.xml")
RESOURCES = Path("android/app/src/main/res")
ICONS = Path(__file__).resolve().parent / "android_res"
NAMESPACE = "http://schemas.android.com/apk/res/android"
ANDROID = "{%s}" % NAMESPACE

if not MANIFEST.exists():
    raise SystemExit("AndroidManifest.xml missing; run flutter create first")

ET.register_namespace("android", NAMESPACE)
tree = ET.parse(MANIFEST)
root = tree.getroot()

permission = "android.permission.INTERNET"
if not any(n.get(ANDROID + "name") == permission for n in root.findall("uses-permission")):
    node = ET.Element("uses-permission", {ANDROID + "name": permission})
    root.insert(0, node)

application = root.find("application")
if application is None:
    raise SystemExit("Android application node missing")
application.set(ANDROID + "label", "Revive Launcher")
# The encrypted session cannot be decrypted after a cloud restore.
application.set(ANDROID + "allowBackup", "false")

activity = next(
    (n for n in application.findall("activity")
     if n.get(ANDROID + "name", "").endswith("MainActivity")),
    None,
)
if activity is None:
    raise SystemExit("MainActivity not found in AndroidManifest.xml")
activity.set(ANDROID + "exported", "true")
activity.set(ANDROID + "launchMode", "singleTop")

# The OAuth return link is handled by supabase_flutter (app_links); Flutter's own
# deep link routing must not also receive it.
flag = "flutter_deeplinking_enabled"
meta = next(
    (n for n in activity.findall("meta-data") if n.get(ANDROID + "name") == flag),
    None,
)
if meta is None:
    meta = ET.SubElement(activity, "meta-data", {ANDROID + "name": flag})
meta.set(ANDROID + "value", "false")

if not any(
    data.get(ANDROID + "scheme") == "revive" and data.get(ANDROID + "host") == "auth"
    for data in activity.findall("intent-filter/data")
):
    intent = ET.SubElement(activity, "intent-filter")
    ET.SubElement(intent, "action", {ANDROID + "name": "android.intent.action.VIEW"})
    for category in ("DEFAULT", "BROWSABLE"):
        ET.SubElement(intent, "category",
                      {ANDROID + "name": "android.intent.category." + category})
    ET.SubElement(intent, "data", {
        ANDROID + "scheme": "revive",
        ANDROID + "host": "auth",
        ANDROID + "path": "/callback",
    })

tree.write(MANIFEST, encoding="utf-8", xml_declaration=True)

# Revive launcher icon.
for folder in sorted(ICONS.glob("mipmap-*")):
    target = RESOURCES / folder.name
    target.mkdir(parents=True, exist_ok=True)
    shutil.copy2(folder / "ic_launcher.png", target / "ic_launcher.png")

print("Android project configured.")
